import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("social-analytics")
DATABASE_PATH = "social_manager.db"


@mcp.tool()
def get_post_engagement_summary(post_id: str, days: int = 30) -> dict:
    if not post_id or not post_id.strip():
        return {"error": "post_id is required"}
    if not isinstance(days, int) or days < 1 or days > 90:
        return {"error": "days must be an integer between 1 and 90"}
    connection = sqlite3.connect(f"file:{DATABASE_PATH}?mode=ro", uri=True)
    try:
        row = connection.execute(
            "SELECT COALESCE(SUM(likes),0), COALESCE(SUM(comments),0), COALESCE(SUM(shares),0), "
            "COALESCE(SUM(impressions),0) FROM post_metrics "
            "WHERE post_id = ? AND metric_date >= date('now', ?)",
            (post_id, f"-{days} days"),
        ).fetchone()
    finally:
        connection.close()
    if row is None:
        return {"error": "no metrics found"}
    likes, comments, shares, impressions = row
    rate = (likes + comments + shares) / impressions if impressions else 0.0
    return {
        "post_id": post_id,
        "days": days,
        "likes": likes,
        "comments": comments,
        "shares": shares,
        "impressions": impressions,
        "engagement_rate": round(rate, 4),
    }
